package org.apache.parquet.format.converter;

import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
import org.apache.parquet.format.ConvertedType;
import org.apache.parquet.format.SchemaElement;
import org.apache.parquet.schema.LogicalTypeAnnotation;
import org.apache.parquet.format.TimeUnit;

public class ParquetMetadataConverterGetLogicalTypeAnnotationTests {

  private final ParquetMetadataConverter converter = new ParquetMetadataConverter();

  @Test
  void convertsStructuralAndTextTypes() {
    assertEquals(
        LogicalTypeAnnotation.stringType(),
        converter.getLogicalTypeAnnotation(ConvertedType.UTF8, null));
    assertEquals(
        LogicalTypeAnnotation.mapType(),
        converter.getLogicalTypeAnnotation(ConvertedType.MAP, null));
    assertEquals(
        LogicalTypeAnnotation.MapKeyValueTypeAnnotation.getInstance(),
        converter.getLogicalTypeAnnotation(ConvertedType.MAP_KEY_VALUE, null));
    assertEquals(
        LogicalTypeAnnotation.listType(),
        converter.getLogicalTypeAnnotation(ConvertedType.LIST, null));
    assertEquals(
        LogicalTypeAnnotation.enumType(),
        converter.getLogicalTypeAnnotation(ConvertedType.ENUM, null));
    assertEquals(
        LogicalTypeAnnotation.jsonType(),
        converter.getLogicalTypeAnnotation(ConvertedType.JSON, null));
    assertEquals(
        LogicalTypeAnnotation.bsonType(),
        converter.getLogicalTypeAnnotation(ConvertedType.BSON, null));
  }

  @Test
  void convertsDateTimeAndIntervalTypes() {
    assertEquals(
        LogicalTypeAnnotation.dateType(),
        converter.getLogicalTypeAnnotation(ConvertedType.DATE, null));
    assertEquals(
        LogicalTypeAnnotation.timeType(true, LogicalTypeAnnotation.TimeUnit.MILLIS),
        converter.getLogicalTypeAnnotation(ConvertedType.TIME_MILLIS, null));
    assertEquals(
        LogicalTypeAnnotation.timeType(true, LogicalTypeAnnotation.TimeUnit.MICROS),
        converter.getLogicalTypeAnnotation(ConvertedType.TIME_MICROS, null));
    assertEquals(
        LogicalTypeAnnotation.timestampType(true, LogicalTypeAnnotation.TimeUnit.MILLIS),
        converter.getLogicalTypeAnnotation(ConvertedType.TIMESTAMP_MILLIS, null));
    assertEquals(
        LogicalTypeAnnotation.timestampType(true, LogicalTypeAnnotation.TimeUnit.MICROS),
        converter.getLogicalTypeAnnotation(ConvertedType.TIMESTAMP_MICROS, null));
    assertEquals(
        LogicalTypeAnnotation.IntervalLogicalTypeAnnotation.getInstance(),
        converter.getLogicalTypeAnnotation(ConvertedType.INTERVAL, null));
  }

  @Test
  void convertsSignedAndUnsignedIntegerTypes() {
    assertEquals(
        LogicalTypeAnnotation.intType(8, true),
        converter.getLogicalTypeAnnotation(ConvertedType.INT_8, null));
    assertEquals(
        LogicalTypeAnnotation.intType(16, true),
        converter.getLogicalTypeAnnotation(ConvertedType.INT_16, null));
    assertEquals(
        LogicalTypeAnnotation.intType(32, true),
        converter.getLogicalTypeAnnotation(ConvertedType.INT_32, null));
    assertEquals(
        LogicalTypeAnnotation.intType(64, true),
        converter.getLogicalTypeAnnotation(ConvertedType.INT_64, null));
    assertEquals(
        LogicalTypeAnnotation.intType(8, false),
        converter.getLogicalTypeAnnotation(ConvertedType.UINT_8, null));
    assertEquals(
        LogicalTypeAnnotation.intType(16, false),
        converter.getLogicalTypeAnnotation(ConvertedType.UINT_16, null));
    assertEquals(
        LogicalTypeAnnotation.intType(32, false),
        converter.getLogicalTypeAnnotation(ConvertedType.UINT_32, null));
    assertEquals(
        LogicalTypeAnnotation.intType(64, false),
        converter.getLogicalTypeAnnotation(ConvertedType.UINT_64, null));
  }

  @Test
  void convertsDecimalUsingSchemaScaleAndPrecision() {
    SchemaElement schemaElement = new SchemaElement();
    schemaElement.scale = 2;
    schemaElement.precision = 10;

    assertEquals(
        LogicalTypeAnnotation.decimalType(2, 10),
        converter.getLogicalTypeAnnotation(ConvertedType.DECIMAL, schemaElement));
  }

  @Test
  void convertsDecimalWithNullSchemaUsingZeroDefaults() {
    assertEquals(
        LogicalTypeAnnotation.decimalType(0, 0),
        converter.getLogicalTypeAnnotation(ConvertedType.DECIMAL, null));
  }

  @Test
  void preservesDecimalScaleWhenPrecisionIsThirtyEight() {
    SchemaElement schemaElement = new SchemaElement();
    schemaElement.scale = 0;
    schemaElement.precision = 38;

    assertEquals(
        LogicalTypeAnnotation.decimalType(0, 38),
        converter.getLogicalTypeAnnotation(ConvertedType.DECIMAL, schemaElement));
  }

  @Test
  void rejectsNullConvertedType() {
    assertThrows(
        RuntimeException.class,
        () -> converter.getLogicalTypeAnnotation(null, null));
  }
}
